import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom';
import bulbOn from '../Assets/Images/light-bulb-on.png';
import bulbOff from '../Assets/Images/lightbult-off.png';
import '../Assets/Stylesheetes/Javascript.css'

function Javascript() {


    // UseState:
    const [isBulbOn, setIsBulbOn] = useState();



    // ##Functions:
    // Click to change the text
    const clickFunction = () => {
        document.getElementById("demo").innerHTML = "Start to learning";
    }

    // Click to bulb on function:
    const clickBulbOn = () => {
        setIsBulbOn(true); // Set bulb status to on
    }

    // Click to bulb off function:
    const clickBulbOff = () => {
        setIsBulbOn(false); // Set bulb status to off
    }

    // Click to visible text:
    const visibleText = () => {
        document.getElementById("none").style.display = "block";
        document.getElementById("none").style.fontSize = "35px";
    }

    // Write text:
    const writetext = () => {
        document.write(5 + 7);
        window.alert("Shiviear cold")
        alert("Cold...")
    }






    // UseEffect:
    useEffect(() => {
        document.getElementById("addition").innerHTML = "Anto " + "Martin";
    }, []);


    // write text:
    useEffect(() => {
        console.log("I am will to be there for them.");
    }, []);


    useEffect(() => {
        let x, y, z;
        x = 5;
        y = 12;
        z = x + y;

        document.getElementById("textValue").innerHTML = "The text value is : " + z + ".";
    }, []);

    // Declare variable:
    useEffect(()=> {
        const nivia = "Nivia Football";
        document.getElementById("delcareVariable").innerHTML = nivia;
    },[]);


    return (
        <div>
            <div className=''>
                <h4 className="logout_style"><Link to={"/"}>Logout</Link></h4>
            </div>

            {/* Text changing */}
            <div className='d-flex justify-content-center align-items-center'>
                <p id='demo' className=''>
                    JvaScript Basics:
                </p>
                <button className='btn btn-info ms-2' type='button' onClick={clickFunction}>Click</button>
            </div>

            {/* Light on off */}
            <div className=''>
                <p>Bulp on of testing..</p>
                <div className='bulp_img'>
                    <img src={isBulbOn ? bulbOn : bulbOff} alt='Bulb' />
                </div>
                <button type='button ' onClick={clickBulbOff}>Bulb Off</button>
                <button type='button' onClick={clickBulbOn}>Bulb On</button>
            </div>

            {/* JavaScript can show hidden HTML elements. */}
            <div>
                <p className='' id='none' style={{ display: 'none' }}>To be a man</p>
                <button className='text' type='button' onClick={visibleText}>Make visible</button>
            </div>

            {/* Small addition */}
            <div>
                <p id='addition'></p>
            </div>

            {/* Write text */}
            <div>
                <div id="write"></div>
                <button onClick={writetext}>ok</button>
            </div>

            {/* Print the pdf */}
            <div>
                <button onClick={() => window.print()}>Print</button>
            </div>

            {/* text with value */}
            <div>
                <p id="textValue"></p>
            </div>

            {/* Variable declaration */}
            <div>
                <p id='delcareVariable'>Test with data</p>
            </div>

        </div>
    )
}

export default Javascript